CREATE TYPE public.app_role AS ENUM ('admin', 'moderator', 'user');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, UNIQUE(user_id, role));
GRANT SELECT ON public.user_roles TO authenticated;
GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY roles_read_own ON public.user_roles FOR SELECT TO authenticated USING (user_id = auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid, _role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = _user_id AND role = _role) $$;
CREATE TABLE public.announcements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, content jsonb NOT NULL DEFAULT '{"type":"doc","content":[]}'::jsonb, created_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.announcements TO anon;
GRANT SELECT, INSERT, UPDATE, DELETE ON public.announcements TO authenticated;
GRANT ALL ON public.announcements TO service_role;
ALTER TABLE public.announcements ENABLE ROW LEVEL SECURITY;
CREATE POLICY announcements_public_read ON public.announcements FOR SELECT TO anon, authenticated USING (true);
CREATE POLICY announcements_admin_insert ON public.announcements FOR INSERT TO authenticated WITH CHECK (public.has_role(auth.uid(), 'admin') AND created_by = auth.uid());
CREATE POLICY announcements_admin_update ON public.announcements FOR UPDATE TO authenticated USING (public.has_role(auth.uid(), 'admin')) WITH CHECK (public.has_role(auth.uid(), 'admin'));
CREATE POLICY announcements_admin_delete ON public.announcements FOR DELETE TO authenticated USING (public.has_role(auth.uid(), 'admin'));
CREATE POLICY announcement_images_admin_select ON storage.objects FOR SELECT TO authenticated USING (bucket_id = 'announcement-images' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY announcement_images_public_select ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'announcement-images' AND EXISTS (SELECT 1 FROM public.announcements a WHERE a.content @> jsonb_build_object('content', jsonb_build_array(jsonb_build_object('type','image','attrs',jsonb_build_object('src',name))))));
CREATE POLICY announcement_images_admin_insert ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'announcement-images' AND public.has_role(auth.uid(), 'admin'));
CREATE POLICY announcement_images_admin_delete ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'announcement-images' AND public.has_role(auth.uid(), 'admin'));